reference.cpp:
#include <cstdio>
#include <vector>

struct Node {
    int val;
    Node* next;
    Node(int v) : val(v), next(nullptr) {}
};

int main() {
    int n;
    scanf("%d", &n);

    Node* head = nullptr;
    Node* tail = nullptr;
    for (int i = 0; i < n; ++i) {
        int v;
        scanf("%d", &v);
        Node* node = new Node(v);
        if (!head) { head = tail = node; }
        else { tail->next = node; tail = node; }
    }

    Node* prev = nullptr;
    Node* cur = head;
    while (cur) {
        Node* nxt = cur->next;
        cur->next = prev;
        prev = cur;
        cur = nxt;
    }
    head = prev;

    bool first = true;
    for (Node* p = head; p; p = p->next) {
        if (!first) printf(" ");
        printf("%d", p->val);
        first = false;
    }
    printf("\n");
    return 0;
}
